<?php require __DIR__.'/bootstrap.php';require __DIR__.'/bootstrap_auth.php';require_login();$tid=require_tour();$editId=(int)($_GET['edit']??0);$edit=null;
if($editId){$q=db()->prepare("SELECT * FROM expenses WHERE id=? AND tour_id=?");$q->execute([$editId,$tid]);$edit=$q->fetch();if(!$edit)redirect('expenses.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$a=$_POST['action']??'add';if($a==='delete'){require_permission('expense.delete');db()->prepare("DELETE FROM expenses WHERE id=? AND tour_id=?")->execute([(int)$_POST['id'],$tid]);audit('DELETE_EXPENSE','expense',(int)$_POST['id']);flash('success','Expense deleted.');}elseif($a==='update'){db()->prepare("UPDATE expenses SET category=?,description=?,amount=?,paid_by=?,expense_date=? WHERE id=? AND tour_id=?")->execute([trim($_POST['category']),trim($_POST['description']),max(0,(float)$_POST['amount']),trim($_POST['paid_by']),$_POST['expense_date'],(int)$_POST['id'],$tid]);audit('UPDATE_EXPENSE','expense',(int)$_POST['id']);flash('success','Expense updated.');}else{db()->prepare("INSERT INTO expenses(tour_id,category,description,amount,paid_by,expense_date,created_by) VALUES(?,?,?,?,?,?,?)")->execute([$tid,trim($_POST['category']),trim($_POST['description']),max(0,(float)$_POST['amount']),trim($_POST['paid_by']),$_POST['expense_date'],$_SESSION['admin_id']]);audit('ADD_EXPENSE','expense',(int)db()->lastInsertId());flash('success','Expense added.');}}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('expenses.php');}
$q=db()->prepare("SELECT * FROM expenses WHERE tour_id=? ORDER BY expense_date DESC,id DESC");$q->execute([$tid]);$rows=$q->fetchAll();$total=array_sum(array_column($rows,'amount'));
?><!doctype html><html><head><?php include __DIR__.'/partials/head.php';?></head><body><?php include __DIR__.'/partials/nav.php';?><main class="wrap"><?php flash_render();?>
<div class="row-actions"><a class="btn secondary" href="cost_calculator.php">🧮 Cost Calculator</a></div><div class="grid2"><section class="card"><h2><?=$edit?'Edit Expense':'Add Expense'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="<?=$edit?'update':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><label>Category<input name="category" required value="<?=h($edit['category']??'')?>"></label><label>Amount<input name="amount" type="number" min="0" step="0.01" required value="<?=h($edit['amount']??'')?>"></label><label>Description<input name="description" value="<?=h($edit['description']??'')?>"></label><label>Paid By<input name="paid_by" value="<?=h($edit['paid_by']??'')?>"></label><label>Date<input name="expense_date" type="date" value="<?=h($edit['expense_date']??date('Y-m-d'))?>"></label><div class="row-actions"><button class="btn primary"><?=$edit?'Update Expense':'Save Expense'?></button><?php if($edit):?><a class="btn secondary" href="expenses.php">Cancel</a><?php endif;?></div></form></section><section class="card"><h2>Total Expenses</h2><div class="stat"><span>Total</span><b><?=money($total)?></b></div></section></div><section class="card"><div class="head"><h2>Expense History</h2><a class="btn secondary" href="summary_print.php?tour_id=<?=$tid?>">Print Summary</a></div><div class="table-wrap responsive-table"><table><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Paid By</th><th>Amount</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $x):?><tr><td data-label="Date"><?=h($x['expense_date'])?></td><td data-label="Category"><?=h($x['category'])?></td><td data-label="Description"><?=h($x['description'])?></td><td data-label="Paid By"><?=h($x['paid_by'])?></td><td data-label="Amount"><?=money($x['amount'])?></td><td data-label="Actions" class="nowrap"><a class="btn secondary" href="expenses.php?edit=<?=$x['id']?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete expense?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$x['id']?>"><?php if(can("expense.delete")):?><?php if(can("expense.delete")):?><button class="btn danger">Delete</button><?php endif;?><?php endif;?></form></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
